import numpy as np
import scipy.stats as st

def close(a, b, rtol: float = 1e-7) -> bool:
    x = np.asarray(a).astype(float).ravel()
    y = np.asarray(b).astype(float).ravel()
    if x.shape != y.shape:
        return False
    for i in range(x.shape[0]):
        u = float(x[i])
        v = float(y[i])
        if not (abs(u - v) <= 1e-9 + rtol * abs(v) or (u != u and v != v)):
            print('mismatch', i, u, v)
            return False
    return True

xs = [-1.5, -0.2, 0.3, 1.1, 2.7]
qs = [0.05, 0.3, 0.5, 0.9]

@test
def test_normal():
    X = st.Normal(mu=0.5, sigma=1.5)
    x = [-1.5, -0.2, 0.3, 1.1, 2.7]
    assert close(X.pdf(x), [0.10934004978399575, 0.23852228611197931, 0.26360789392387846, 0.24551342686888222, 0.09072165494151868])
    assert close(X.cdf(x), [0.09121121972586788, 0.32036919090127036, 0.446964883376386, 0.6554217416103242, 0.928766622586014])
    assert close(X.ccdf(x), [0.9087887802741321, 0.6796308090987296, 0.553035116623614, 0.3445782583896758, 0.0712333774139861])
    assert close(X.icdf(qs), [-1.967280440427209, -0.28660076906206133, 0.5, 2.4223273483169008])
    assert close([X.mean(), X.variance()], [0.5, 2.25], 1e-6)

@test
def test_uniform():
    X = st.Uniform(a=-1.0, b=3.0)
    x = [-1.5, -0.2, 0.3, 1.1, 2.7]
    assert close(X.pdf(x), [0.0, 0.25, 0.25, 0.25, 0.25])
    assert close(X.cdf(x), [0.0, 0.2, 0.325, 0.525, 0.925])
    assert close(X.ccdf(x), [1.0, 0.8, 0.675, 0.475, 0.07499999999999996])
    assert close(X.icdf(qs), [-0.8, 0.19999999999999996, 1.0, 2.6])
    assert close([X.mean(), X.variance()], [1.0, 1.3333333333333333], 1e-6)

