@test
def test_binomial():
    X = st.Binomial(n=10, p=0.3)
    x = [0.0, 1.0, 3.0, 5.0, 8.0]
    assert close(X.pmf(x), [0.02824752490000001, 0.12106082099999993, 0.2668279319999998, 0.10291934519999994, 0.001446700499999999])
    assert close(X.cdf(x), [0.028247524900000005, 0.1493083458999999, 0.6496107184000002, 0.9526510126000001, 0.9998563141])
    assert close(X.ccdf(x), [0.9717524751, 0.8506916541000001, 0.3503892815999998, 0.04734898739999998, 0.00014368589999999996])
    assert close(X.icdf(qs), [1.0, 2.0, 3.0, 5.0])
    assert close([X.mean(), X.variance()], [3.0, 2.0999999999999996], 1e-6)

@test
def test_mixture():
    X = st.Mixture([st.Normal(mu=-1.0, sigma=0.5), st.Uniform(a=0.0, b=2.0)], weights=[0.3, 0.7])
    x = [-1.5, -0.2, 0.3, 1.1, 2.7]
    assert close(X.pdf(x), [0.145182434711486, 0.06655250080767332, 0.3581497815402113, 0.3500353658406539, 3.076652182077998e-13])
    assert close(X.cdf(x), [0.04759657617943712, 0.2835602124901326, 0.40360164359288436, 0.6849959962752952, 0.9999999999999796])
    assert close(X.ccdf(x), [0.9524034238205628, 0.7164397875098674, 0.5963983564071156, 0.3150040037247047, 2.0427674671860038e-14])
    assert close(X.icdf(qs), [-1.4837107830508502, 0.017901489903029356, 0.5721421156050066, 1.7142857386315267])
    assert close([X.mean(), X.variance()], [0.39999999999999997, 1.1483333333333332], 1e-6)

@test
def test_truncate():
    X = st.truncate(st.Normal(mu=0.5, sigma=1.5), -1.0, 2.0)
    x = [-1.5, -0.2, 0.3, 1.1, 2.7]
    assert close(X.pdf(x), [0.0, 0.3493861980580821, 0.38613146527081066, 0.3596267844995371, 0.0])
    assert close(X.cdf(x), [0.0, 0.23687772967412357, 0.4223144383582164, 0.7276609547977563, 1.0])
    assert close(X.ccdf(x), [1.0, 0.7631222703258767, 0.5776855616418066, 0.2723390452022439, 0.0])
    assert close(X.icdf(qs), [-0.8014928281280325, -0.023829898685323148, 0.5, 1.6235218984543553])
    assert close([X.mean(), X.variance()], [0.5, 0.6550314632387848], 1e-6)

