    x = [-1.5, -0.2, 0.3, 1.1, 2.7]
    assert close(X.pdf(x), [0.14970847842901716, 0.47976534872392734, 0.39858406990640893, 0.1316708691642457, 0.0006091134198313748])
    assert close(X.cdf(x), [0.06903121116502436, 0.5132473972551588, 0.7392155306334603, 0.9489421648711962, 0.9998785990832831])
    assert close(X.ccdf(x), [0.9309687888349756, 0.4867526027448412, 0.26078446936653965, 0.051057835128803845, 0.00012140091671690412])
